289		for name, body := range map[string]string{
290			"bad direction":    singleRuleBody("payments", "bad-dir", "tier=backend", "sideways", "allow", 80, 80, `{}`),
291			"port below range": singleRuleBody("payments", "bad-port", "tier=backend", "ingress", "allow", 0, 80, `{}`),
292			"port above range": singleRuleBody("payments", "bad-port2", "tier=backend", "ingress", "allow", 1, 65536, `{}`),
