297			}
298			assertExactErrorShape(t, recorder, "InvalidNetPolicyInputError")
299			assertSafeErrorMessage(t, recorder)
300		}
301	
302		// Same-content retry with reordered pluginParams members: 200, original record.
303		retryBody := singleRuleBody("payments", "allow-web", "tier=backend", "ingress", "allow", 100, 200,
304			`{"zone": "east", "mode": "enforce"}`)
305		recorder = doRequest(router, http.MethodPost, "/v1/net-policies", retryBody)
306		if recorder.Code != http.StatusOK {
307			t.Fatalf("retry status = %d, want %d: %s", recorder.Code, http.StatusOK, recorder.Body.String())
308		}
309		var resp map[string]any
310		if err := json.Unmarshal(recorder.Body.Bytes(), &resp); err != nil {
311			t.Fatalf("decode retry: %v", err)
312		}
313		if !reflect.DeepEqual(resp, clash) {
314			t.Fatalf("retry record = %v, want the original %v", resp, clash)
315		}
